@extends('layouts.front') @section('content')@php($severityBadge = ['low' => 'success', 'medium' => 'info', 'high' => 'warning', 'critical' => 'danger'])<section class="page-hero compact"><span class="eyebrow">SURVEILLANCE CONTINUE</span><h1>Alertes<br><em>en temps réel.</em></h1><p>Les alertes remontées par les zones et les incidents du réseau AquaSecure.</p></section><section class="section">@if(empty($alerts))<p>Aucune alerte pour le moment.</p>@else<div class="panel table-wrap"><table><thead><tr><th>Alerte</th><th>Message</th><th>Zone</th><th>Gravité</th><th>État</th><th>Date</th></tr></thead><tbody>@foreach($alerts as $alert)<tr><td><strong>{{ $alert['type'] }}</strong></td><td>{{ \Illuminate\Support\Str::limit($alert['message'], 80) }}</td><td>{{ $alert['zone'] }}</td><td><x-ui.badge :variant="$severityBadge[$alert['severityLevel']] ?? 'info'">{{ $alert['severity'] }}</x-ui.badge></td><td>{{ $alert['status'] }}</td><td>{{ $alert['date'] }}</td></tr>@endforeach</tbody></table></div>@endif</section>@endsection
